package com.focusguard.app.challenge

import com.focusguard.app.data.GradeStore

/**
 * 具有深度思维量的高难度本地题库。
 *
 * 题目设计原则：
 * 1. 坚决杜绝一眼秒杀题，以数学思维推导（导数极值、二次函数单调性、数列裂项相消、圆锥曲线弦长性质、排列组合）和物理综合受力动量为主；
 * 2. 严格按学段隔离，高中阶段绝不抽小学题；
 * 3. 手机端支持 [A] [B] [C] [D] 快捷一键作答。
 */
object QuestionBank {

    data class Item(
        val grade: Int,
        val subject: String,
        val stream: String, // SCIENCE, HUMANITIES, ALL
        val question: String,
        val options: List<String>,
        val answer: String,
        val explanation: String
    )

    val items: List<Item> = listOf(
        Item(3, "数学", "ALL", "设函数 f(x) = x³ - 3x² + ax + 1。若 f(x) 在区间 (1, 3) 内单调递减，则实数 a 的取值范围是（ ）", listOf("A. a ≤ -9", "B. a ≤ 0", "C. a ≤ -3", "D. a ≥ 9"), "A", "导数 f'(x) = 3x² - 6x + a ≤ 0 在 (1, 3) 恒成立。二次函数对称轴 x=1，在 x ∈ (1,3) 上递增，最大值在端点 x=3 处，f'(3) = 27 - 18 + a = 9 + a ≤ 0，得 a ≤ -9。"),
        Item(3, "数学", "ALL", "已知函数 f(x) = e^x - ax 在 R 上单调递增，则实数 a 的取值范围是（ ）", listOf("A. a ≤ 0", "B. a ≤ 1", "C. a ≤ e", "D. a ≥ 0"), "A", "导数 f'(x) = e^x - a ≥ 0 恒成立，即 a ≤ e^x 恒成立。因为 x ∈ R 时 e^x > 0 且下界趋近于 0，所以 a ≤ 0。"),
        Item(3, "数学", "ALL", "函数 f(x) = ln x - x + 1 的最大值为（ ）", listOf("A. 0", "B. 1", "C. e", "D. 不存在"), "A", "定义域 x > 0。导数 f'(x) = 1/x - 1 = (1 - x)/x。当 x ∈ (0, 1) 时 f'(x) > 0；当 x > 1 时 f'(x) < 0。因此在 x = 1 处取得极大值即最大值 f(1) = ln 1 - 1 + 1 = 0。"),
        Item(3, "数学", "ALL", "已知数列 {a_n} 满足 a_1 = 1，a_(n+1) = 2a_n + 1，则数列通项 a_n 等于（ ）", listOf("A. 2^n - 1", "B. 2^(n-1)", "C. 2^(n+1) - 3", "D. n²"), "A", "两边加 1 得 a_(n+1) + 1 = 2(a_n + 1)。所以 {a_n + 1} 是以 a_1 + 1 = 2 为首项、公比为 2 的等比数列，a_n + 1 = 2 * 2^(n-1) = 2^n，故 a_n = 2^n - 1。"),
        Item(3, "数学", "ALL", "在等差数列 {a_n} 中，前 n 项和为 S_n。若 S_9 = 54，则 a_2 + a_5 + a_8 等于（ ）", listOf("A. 12", "B. 18", "C. 24", "D. 36"), "B", "由等差数列求和性质 S_9 = 9 * a_5 = 54，解得 a_5 = 6。又由等差中项性质 a_2 + a_8 = 2a_5，因此 a_2 + a_5 + a_8 = 3a_5 = 18。"),
        Item(3, "数学", "ALL", "数列 {1 / [n(n+1)]} 的前 100 项和等于（ ）", listOf("A. 99/100", "B. 100/101", "C. 101/102", "D. 1"), "B", "裂项相消法：1/[n(n+1)] = 1/n - 1/(n+1)。前 100 项求和 S_100 = (1 - 1/2) + (1/2 - 1/3) + ... + (1/100 - 1/101) = 1 - 1/101 = 100/101。"),
        Item(3, "数学", "ALL", "过双曲线 x²/4 - y²/b² = 1 的右焦点作垂直于实轴的弦，若该弦长等于实轴长，则双曲线离心率 e 为（ ）", listOf("A. √2", "B. √3", "C. 2", "D. √5"), "A", "通径长为 2b²/a，实轴长为 2a。依题意 2b²/a = 2a => b² = a²。离心率 e = c/a = √(a²+b²)/a = √(2a²)/a = √2。"),
        Item(3, "数学", "ALL", "已知椭圆 C: x²/25 + y²/16 = 1 的左右焦点为 F1, F2，点 P 为椭圆上一点。若 ∠F1PF2 = 90°，则 △F1PF2 的面积为（ ）", listOf("A. 9", "B. 12", "C. 16", "D. 25"), "C", "a=5, b=4, c=3。焦点三角形面积公式 S = b² * tan(θ/2)。此处 θ=90°，tan(45°)=1，故 S = 4² * 1 = 16。"),
        Item(3, "数学", "ALL", "直线 y = kx + 1 与圆 x² + y² = 1 相交于 A, B 两点，若弦长 |AB| = √2，则斜率 k 的绝对值等于（ ）", listOf("A. 1", "B. √2", "C. √3", "D. 2"), "A", "圆心到直线的距离 d = √(R² - (|AB|/2)²) = √(1 - 1/2) = √2/2。点到直线距离公式 d = |0 - 0 + 1| / √(1 + k²) = 1/√(1+k²) = 1/√2 => 1+k² = 2 => |k| = 1。"),
        Item(3, "数学", "ALL", "将 4 名学生分配到 3 个不同的班级，每个班级至少分 1 名学生，不同的分配方案共有（ ）种", listOf("A. 24", "B. 36", "C. 48", "D. 72"), "B", "先将 4 人分为 2, 1, 1 三组，分法为 C(4,2)/1! = 6 种；再将三组全排列分给 3 个班级：6 * A(3,3) = 6 * 6 = 36 种。"),
        Item(3, "数学", "ALL", "(x - 2/x)^6 的展开式中，常数项为（ ）", listOf("A. -160", "B. 160", "C. -240", "D. 240"), "A", "通项公式 T_(r+1) = C(6, r) * x^(6-r) * (-2/x)^r = C(6, r) * (-2)^r * x^(6-2r)。令 6-2r = 0 得 r = 3。常数项为 C(6, 3) * (-2)³ = 20 * (-8) = -160。"),
        Item(3, "数学", "ALL", "甲乙两人独立破译一份密码，各自破译出的概率分别为 0.6 和 0.5，则密码能被成功破译的概率为（ ）", listOf("A. 0.3", "B. 0.7", "C. 0.8", "D. 0.9"), "C", "至少一人破译的对立事件为两人都未破译。P = 1 - (1 - 0.6) * (1 - 0.5) = 1 - 0.4 * 0.5 = 1 - 0.2 = 0.8。"),
        Item(3, "物理", "SCIENCE", "质量为 m 的小球用长为 L 的轻绳悬挂在天花板上，从水平位置无初速释放，小球摆到最低点时轻绳受到的拉力大小为（ ）", listOf("A. mg", "B. 2mg", "C. 3mg", "D. 4mg"), "C", "机械能守恒：mgL = 1/2 * m * v² => v² = 2gL。在最低点合外力提供向心力：T - mg = m * v²/L = 2mg，解得拉力 T = 3mg。"),
        Item(3, "物理", "SCIENCE", "质量为 M 的木块静止在光滑水平面上，质量为 m 的子弹以初速度 v0 水平击中木块并留在其中，系统损失的机械能为（ ）", listOf("A. 1/2 * m * v0²", "B. [M / (2(M + m))] * m * v0²", "C. [m / (2(M + m))] * M * v0²", "D. 0"), "B", "动量守恒 mv0 = (M+m)v => v = mv0/(M+m)。初动能 E1 = 1/2 * m * v0²，末动能 E2 = 1/2 * (M+m) * v² = m²v0² / [2(M+m)]。损失 ΔE = E1 - E2 = [M / (2(M+m))] * m * v0²。"),
        Item(3, "物理", "SCIENCE", "两颗地球人造卫星 A 和 B，轨道半径之比 rA : rB = 1 : 4，则它们绕地球做匀速圆周运动的周期之比 TA : TB 为（ ）", listOf("A. 1 : 2", "B. 1 : 4", "C. 1 : 8", "D. 1 : 16"), "C", "根据开普勒第三定律 r³/T² = k，得 (TA/TB)² = (rA/rB)³ = (1/4)³ = 1/64，故 TA : TB = 1 : 8。"),
        Item(3, "物理", "SCIENCE", "在匀强磁场 B 中，阻值为 R、长为 L 的金属棒以速度 v 垂直切割磁感线，棒受到的安培力阻力大小为（ ）", listOf("A. B²L²v / R", "B. BLv / R", "C. B²L²v² / R", "D. BLv² / R²"), "A", "感应电动势 E = BLv，感应电流 I = E/R = BLv/R。安培力 F = BIL = B * (BLv/R) * L = B²L²v / R。"),
        Item(3, "化学", "SCIENCE", "在密闭容器中充入 1mol N2 和 3mol H2 发生反应 N2 + 3H2 <=> 2NH3，达到平衡时 N2 的转化率为 20%，则平衡时容器内气体总物质的量为（ ）mol", listOf("A. 3.2", "B. 3.4", "C. 3.6", "D. 3.8"), "C", "消耗 N2 为 1 * 20% = 0.2 mol，消耗 H2 为 0.6 mol，生成 NH3 为 0.4 mol。平衡时 N2: 0.8mol, H2: 2.4mol, NH3: 0.4mol，总计 0.8 + 2.4 + 0.4 = 3.6 mol。"),
        Item(3, "化学", "SCIENCE", "完全中和 20 mL 0.1 mol/L 稀盐酸溶液，需要 0.05 mol/L Ba(OH)2 溶液的体积为（ ）mL", listOf("A. 10", "B. 20", "C. 40", "D. 50"), "B", "n(H⁺) = 0.02 L * 0.1 mol/L = 0.002 mol。Ba(OH)2 是二元强碱，每个分子提供 2 个 OH⁻，故所需 Ba(OH)2 物质的量为 0.001 mol。体积 V = 0.001 / 0.05 = 0.02 L = 20 mL。"),
        Item(3, "地理", "HUMANITIES", "某地夏至日正午太阳高度角为 75°，且太阳位于正南方；冬至日正午太阳高度角为 28°，该地的地理纬度为（ ）", listOf("A. 38.5°N", "B. 31.5°N", "C. 23.5°N", "D. 35°N"), "A", "正午太阳高度 H = 90° - |φ - δ|。夏至赤纬 δ = 23.5°N，太阳在正南说明当地纬度 φ > 23.5°N。75° = 90° - (φ - 23.5°) => φ = 38.5°N。代入冬至验证：90° - (38.5° + 23.5°) = 90° - 62° = 28°，完全吻合。"),
        Item(3, "历史", "HUMANITIES", "唐德宗建中元年（780年），宰相杨炎推行两税法，其最根本的改革特征在于（ ）", listOf("A. 废除人头税全部摊入田亩", "B. 改变以人丁为主的赋税标准，转向以资产和田亩为主", "C. 实行实物地租与劳役结合", "D. 彻底解决了封建土地兼并"), "B", "两税法'唯以资产为宗，不以丁身为本'，放松了国家对农民的人身控制，标志着中国古代赋税制度由以人丁为主转向以财产为主的重大转变。"),
        Item(4, "高数", "ALL", "极限 lim(x->0) (e^x - 1 - x) / x² 的值为（ ）", listOf("A. 0", "B. 1/2", "C. 1", "D. 2"), "B", "泰勒展开 e^x = 1 + x + x²/2 + o(x²)，分子为 x²/2 + o(x²)，除以 x² 极限为 1/2。亦可连续使用两次洛必达法则。"),
        Item(4, "高数", "ALL", "定积分 ∫[0, π] x * sin x dx 的值为（ ）", listOf("A. 1", "B. 2", "C. π", "D. 2π"), "C", "分部积分法：∫ x sin x dx = -x cos x + ∫ cos x dx = -x cos x + sin x。代入上下限：(-π cos π + sin π) - (0) = π*(-(-1)) = π。"),
        Item(4, "线代", "ALL", "设 3 阶方阵 A 的特征值为 1, 2, 3，则伴随矩阵 A* 的行列式 |A*| 等于（ ）", listOf("A. 6", "B. 12", "C. 36", "D. 216"), "C", "矩阵行列式等于特征值之积：|A| = 1*2*3 = 6。对于 n 阶方阵，|A*| = |A|^(n-1)。此处 n=3，故 |A*| = 6^(3-1) = 6² = 36。"),
        Item(4, "计算机", "ALL", "哈希表采用线性探测法解决冲突，哈希函数 H(k) = k mod 7，装填因子为 0.7，查找成功的最少探测次数为（ ）", listOf("A. 0", "B. 1", "C. 2", "D. 7"), "B", "若目标元素首次散列位置即匹配，无需探测冲突槽位，最少比较 1 次即可命中。"),
        Item(2, "数学", "ALL", "若关于 x 的一元二次方程 x² - 4x + k = 0 有两个不相等的实数根，则实数 k 的取值范围是（ ）", listOf("A. k < 4", "B. k ≤ 4", "C. k > 4", "D. k ≠ 4"), "A", "判别式 Δ = b² - 4ac = (-4)² - 4*1*k = 16 - 4k > 0，解得 k < 4。"),
        Item(2, "数学", "ALL", "在直角三角形 ABC 中，∠C = 90°，若 AC = 6，BC = 8，则斜边 AB 上的高线长为（ ）", listOf("A. 4.8", "B. 5", "C. 2.4", "D. 10"), "A", "斜边 AB = √(6² + 8²) = 10。由面积等式 1/2 * AC * BC = 1/2 * AB * h，即 6 * 8 = 10 * h，解得 h = 4.8。"),
        Item(2, "物理", "ALL", "底面积为 100 cm² 的圆柱形容器内装有水，放入一个重 6N 的木块漂浮在水面上（g 取 10N/kg），水面上升的高度为（ ）cm", listOf("A. 0.6", "B. 6", "C. 12", "D. 60"), "B", "木块漂浮受浮力 F浮 = G = 6N。排开水质量 m排 = 6N / 10N/kg = 0.6kg = 600g。水的密度为 1g/cm³，故排开水体积 V = 600 cm³。液面上升 Δh = V / S = 600 / 100 = 6 cm。"),
        Item(1, "数学", "ALL", "笼子里有若干只鸡和兔，从上面数有 35 个头，从下面数有 94 只脚。笼子里兔子的数量是（ ）只", listOf("A. 12", "B. 23", "C. 14", "D. 21"), "A", "鸡兔同笼假设计算：假设全是鸡，则有 35 * 2 = 70 只脚，实际多了 94 - 70 = 24 只脚。每只兔子多 2 只脚，故兔子有 24 / 2 = 12 只，鸡有 23 只。"),
        Item(1, "数学", "ALL", "甲乙两地相距 360 千米，客车和货车同时从两地相对开出，3 小时后相遇。已知客车每小时行 70 千米，货车每小时行（ ）千米", listOf("A. 40", "B. 50", "C. 60", "D. 70"), "B", "两车速度之和为 360 ÷ 3 = 120 千米/小时。货车速度 = 120 - 70 = 50 千米/小时。"),
    )

    /**
     * 按学段与选科方向筛选适配的高难度题目。
     */
    fun find(grade: GradeStore.Grade, stream: GradeStore.Stream): List<Item> {
        val g = grade.level
        val s = stream.id
        return items.filter { item ->
            item.grade == g && (s == "ALL" || item.stream == "ALL" || item.stream == s)
        }
    }
}
